/**
 * A stand-in `@weibo-ai/weibo-cli`, laid out exactly like the npm package.
 *
 * ## 为什么假 CLI 要放进仓库、而不是只留在某个 worktree 的 tmp 里
 *
 * v0.2.28 起，微博的 GUI 验收靠 PATH 上的这个包来替代真实 CLI。它当时只存在于
 * `tmp/`（被 `.gitignore` 排除），于是换一台机器就复现不了——而「复现不了」
 * 恰好是这一版最想消灭的那种证据。
 *
 * 放进 `test/fixtures/` 之后，`DESKTOP_E2E_WEIBO` 的启动脚本可以直接把它挂到
 * PATH 上，任何人 clone 下来都能跑同一套验收。它只在测试里被引用，产品代码
 * 永远不知道自己面对的是一个假包——替换发生在文件系统与 PATH 这个产品本来就
 * 相信的边界上。
 *
 * ## 它能证明什么，不能证明什么
 *
 * - **能**：GUI 驱动的是真实适配器、真实 CLI 调用层、真实投影、真实采集器、
 *   真实分析器，一路到候选。
 * - **不能**：微博的 API 真的这样返回。这里的载荷是按官方手册与
 *   `commands show` 的 schema 写的；真实响应形态另有 `v0233-paging-states`
 *   与 `v0232-weibo-real-shape` 两组用例钉住。
 *
 * ## 场景由 `FAKE_WEIBO_HOME` 决定
 *
 * ```json
 * { "doctor": "ok" | "not_authenticated" | "service_inactive",
 *   "catalog": "full" | "empty",
 *   "status": { ... },
 *   "comments": [ ... ],
 *   "statusFailure": "quota" | "mismatch" | "not_found",
 *   "commentFailure": "quota" | "rate_limit" | "forbidden" | "timeout" | "bad_json",
 *   "cursor": "zero" | "string_zero" | "missing" | "positive",
 *   "emptyWithTotal": true }
 * ```
 *
 * 每次调用都追加到 `FAKE_WEIBO_LOG`，测试因此可以断言产品发出的**确切 argv**——
 * 「传的是 mid 还是 URL」这种事是量出来的，不是假设的。
 */

import { appendFileSync, readFileSync } from 'node:fs'

const args = process.argv.slice(2)
const joined = args.join(' ')

const logPath = process.env.FAKE_WEIBO_LOG
if (logPath !== undefined && logPath !== '') {
  appendFileSync(logPath, `${JSON.stringify(args)}\n`, 'utf8')
}

function home() {
  const path = process.env.FAKE_WEIBO_HOME
  if (path === undefined || path === '') return {}
  try {
    return JSON.parse(readFileSync(path, 'utf8'))
  } catch {
    return {}
  }
}

const config = home()

/** The status this fake account has access to. Ids are 16-digit strings on purpose. */
const DEFAULT_STATUS = {
  id: '5021243409116023',
  idstr: '5021243409116023',
  text:
    '今天把家里那台用了十年的冰箱换掉了。旧的还能制冷，只是压缩机一启动，' +
    '整间屋子都跟着嗡。新的是变频的，站在旁边几乎听不见。',
  created_at: 'Tue Nov 04 09:12:00 +0800 2025',
  user: { id: '7788', idstr: '7788', screen_name: '被围观的博主' },
  comments_count: 3,
  pic_urls: [],
}

/** Three comments: two bystanders and one that disagrees — the argument the AI must find. */
const DEFAULT_COMMENTS = [
  {
    id: '6001',
    idstr: '6001',
    text: '十年了还留着，太恋旧了吧。',
    created_at: 'Tue Nov 04 09:20:00 +0800 2025',
    user: { id: '1001', idstr: '1001', screen_name: '先说话的' },
    reply_comment_total: 0,
  },
  {
    id: '6002',
    idstr: '6002',
    text: '噪音大就换？这逻辑说得通吗，先修一下不行？',
    created_at: 'Tue Nov 04 09:24:00 +0800 2025',
    user: { id: '1002', idstr: '1002', screen_name: '后说话的' },
    reply_comment_total: 0,
  },
  {
    id: '6003',
    idstr: '6003',
    text: '我赞成换，能效差的老冰箱是真费电。',
    created_at: 'Tue Nov 04 09:31:00 +0800 2025',
    user: { id: '1003', idstr: '1003', screen_name: '也说话的' },
    reply_comment_total: 0,
  },
]

const out = (text) => {
  process.stdout.write(text.endsWith('\n') ? text : `${text}\n`)
}

const fail = (status, code, message) => {
  // The official CLI writes a JSON envelope to stderr when `--output json` is explicit.
  process.stderr.write(JSON.stringify({ success: false, status, code, message }))
  process.exit(1)
}

// ── built-ins ──────────────────────────────────────────────────────────────

if (joined === '' || joined.startsWith('--help') || joined === '-h') {
  out('weibo-cli 0.9.8\nUsage: weibo <group> <action> [flags]')
  process.exit(0)
}

if (joined.startsWith('version')) {
  out('weibo-cli 0.9.8')
  process.exit(0)
}

if (joined.startsWith('doctor')) {
  const mode = config.doctor ?? 'ok'
  if (mode === 'ok') {
    out('√ 注册或登录')
    out('√ 完成开发者认证')
    out('√ 开通服务')
    // Real doctor writes a lot of guidance prose after the steps. Included so a parser
    // that merely looks for words like 认证/登录 anywhere in the output is exposed.
    out('')
    out('提示：如需开通服务，请在控制台完成开发者认证并领取体验服务。')
    process.exit(0)
  }
  if (mode === 'not_authenticated') {
    // 真实 CLI 在没有令牌时的原话（2026-11-07 实测）。保留它，是因为
    // `classifyFailure` 的第一版正则一条都没匹配上这段文字。
    out('× 注册或登录')
    out('× 完成开发者认证')
    out('× 开通服务')
    out('')
    out('缺少登录令牌。请优先确认是否有账号，无账号请先注册，有账号请登录')
    out('B) 登录-已有微博账号：请运行 `weibo-cli auth login`；无图形界面可显式使用 `weibo-cli auth login --device`。')
    process.exit(0)
  }
  if (mode === 'service_inactive') {
    out('√ 注册或登录')
    out('× 完成开发者认证')
    out('× 开通服务')
    process.exit(0)
  }
  if (mode === 'expired') {
    out('√ 注册或登录')
    out('√ 完成开发者认证')
    out('× 开通服务')
    out('')
    out('体验服务已过期。')
    process.exit(0)
  }
  out('× 注册或登录')
  process.exit(0)
}

if (joined.startsWith('commands list')) {
  if (config.catalog === 'empty') {
    out(JSON.stringify({ commands: [], total: 75, available_count: 0 }))
  } else {
    out(
      JSON.stringify({
        commands: [
          { group: 'statuses', action: 'show_batch/biz', access: 'allowed' },
          { group: 'comments', action: 'list/biz', access: 'allowed' },
          { group: 'comments', action: 'to_me/biz', access: 'allowed' },
        ],
        total: 3,
        available_count: 3,
      }),
    )
  }
  process.exit(0)
}

if (joined.startsWith('commands show')) {
  // The schema is what the invocation planner reasons over. `--ids` for the status read,
  // `--id` + `--page` + `--count` for comments: the shapes the official manual documents.
  const which = joined.replace('commands show', '').trim()
  if (which.includes('statuses')) {
    out(JSON.stringify({ group: 'statuses', action: 'show_batch/biz', flags: [{ name: 'ids', required: true }] }))
    process.exit(0)
  }
  if (which.includes('comments')) {
    out(
      JSON.stringify({
        group: 'comments',
        action: 'list/biz',
        flags: [
          { name: 'id', required: true },
          { name: 'page', required: false },
          { name: 'count', required: false },
        ],
      }),
    )
    process.exit(0)
  }
  fail(404, 'COMMAND_NOT_FOUND', `unknown command ${which}`)
}

// ── platform reads ─────────────────────────────────────────────────────────

if (joined.startsWith('statuses show_batch/biz')) {
  const failure = config.statusFailure
  if (failure === 'quota') fail(429, 'TRIAL_API_QUOTA_EXCEEDED', '体验服务接口次数已用完')
  if (failure === 'rate_limit') fail(429, 'RATE_LIMITED', '请求过于频繁')
  if (failure === 'not_found') fail(404, 'NOT_FOUND', '微博不存在或已被删除')
  if (failure === 'unauthorized') fail(401, 'TOKEN_EXPIRED', '登录凭证已过期')
  if (failure === 'mismatch') {
    out(JSON.stringify({ idstr: '9999999999999999', text: '这是一条完全不同的微博。' }))
    process.exit(0)
  }
  if (failure === 'bad_json') {
    out('{"idstr": "5021243409116023", "text":')
    process.exit(0)
  }
  out(JSON.stringify(config.status ?? DEFAULT_STATUS))
  process.exit(0)
}

if (joined.startsWith('comments list/biz') || joined.startsWith('comments show/biz')) {
  const failure = config.commentFailure
  if (failure === 'quota') fail(429, 'QUOTA_EXCEEDED', '积分余额不足')
  if (failure === 'rate_limit') fail(429, 'RATE_LIMITED', '请求过于频繁')
  if (failure === 'forbidden') fail(403, 'FORBIDDEN', '没有读取评论的权限')
  if (failure === 'expired') fail(403, 'TRIAL_EXPIRED', '体验服务已过期')
  if (failure === 'timeout') {
    // 不返回：让调用方的超时路径真的被走到，而不是靠断言里假装它超时了。
    setTimeout(() => process.exit(0), 60_000)
  } else {
    const page = Number(/--page (\d+)/.exec(joined)?.[1] ?? '1')
    const comments = config.comments ?? DEFAULT_COMMENTS
    const rows = page === 1 ? comments : []

    /**
     * 游标形态由 `cursor` 决定，默认是真实的「末页给 0」。
     *
     * | 值 | 服务端回的 `next_cursor` | 期望的判定 |
     * | --- | --- | --- |
     * | `zero`（默认） | 数字 `0` | `done` |
     * | `string_zero` | 字符串 `"0"` | `done` |
     * | `missing` | 字段不存在 | `unknown` |
     * | `positive` | 一个正数 | `more` |
     */
    const cursorMode = config.cursor ?? 'zero'
    const cursor =
      cursorMode === 'missing'
        ? {}
        : cursorMode === 'positive'
          ? { next_cursor: 4769389788533551 }
          : cursorMode === 'string_zero'
            ? { next_cursor: '0' }
            : { next_cursor: 0 }

    // 「空页 + 声明总数非零」：平台刚说有评论，一页 0 条不能当成「没有评论」。
    const rowsForPage = config.emptyWithTotal === true && page === 1 ? [] : rows

    out(
      JSON.stringify({
        comments: rowsForPage,
        has_more: rowsForPage.length > 0 && cursorMode === 'positive',
        total_number: config.totalNumber ?? comments.length,
        ...cursor,
      }),
    )
    process.exit(0)
  }
}

// ── writes: this build must never reach here ───────────────────────────────

if (args[0] === 'comments' && !/^(list|show)/.test(args[1] ?? '')) {
  fail(403, 'WRITE_NOT_AUTHORISED', '本构建没有微博写入授权')
}

if (/status(es)?\s+(create|update|repost|destroy|share)|publish|send/i.test(joined)) {
  // Recorded in the log *and* refused, so a test can prove two things at once: the
  // product tried (a defect) and the platform did not accept it (containment).
  fail(403, 'WRITE_NOT_AUTHORISED', '本构建没有微博写入授权')
}

fail(404, 'COMMAND_NOT_FOUND', `unknown command ${joined}`)
